sqlMap.select:
SELECT SM.SKUKEY , SM.SKUKEY AS MATNR , SM.DESC01 , SM.DESC02 , SM.DUOMKY AS UOMKEY , SM.ASKU05 , NVL(( SELECT SUM(QTSIWH) AS QTSIWH FROM STKKY ST WHERE WAREKY = #WAREKY# -- 거점 V AND OWNRKY = SM.OWNRKY -- 화주 (IMV)
AND SKUKEY = SM.SKUKEY -- 품번 AND QTSIWH > 0 AND QTSPMO = 0 AND AREAKY NOT IN ('SHP','SYS') AND LOTA06 = '00'
),0) AS QTSIWH , NVL(( SELECT SUM(QTSIWH) AS QTSIWH FROM STKKY ST WHERE WAREKY = #WAREKY# -- 거점 AND OWNRKY = SM.OWNRKY -- 화주 (IMV) AND SKUKEY = SM.SKUKEY -- 품번 AND QTSPMO = 0 AND QTSIWH > 0 AND AREAKY NOT IN ('SHP','SYS') AND LOTA06 = '00' ),0) AS QTTTWH FROM SKUMA SM WHERE SM.OWNRKY = #OWNRKY# AND SM.SKUKEY = #SKUKEY#
